import {fullChartSection,bindFullChart,updateFullChartSelection,fingeringCaption} from './full-chart.js';
import {brassDisplayKeys,brassDiagram,isTriggerKey} from './brass.js';
import {bindReferenceDrag} from './reference-input.js';
import {silhouetteDefinitions,silhouetteImage} from './silhouettes.js';
import {DEFAULT_ALTERNATES,answerFingerings,nextAnswerIndex} from './answers.js';
import {studentLevels,studentLevel,studentPreset,questLogo,uiIcon} from './student-ui.js';
import {playNoteTone,playAnswerTone,playIncorrectTone,NOTE_TONE_MS} from './audio.js';
import {accentPresets,loadPreferences,applyPreferences,restoreSoundDefaults} from './preferences.js';
import {bindChartDrag} from './drag.js';
import {newClock,elapsedMs,pauseClock,resumeClock,timeExpired,formatTime,parseTimeLimit,validTimeLimit} from './timing.js';
import {decodeSettings,settingsUrl} from './share.js';
import {defaultPractice,rangeNotes,practicePool,withAlternates,noteAllowed} from './practice.js';
import {instruments,tiers,sources,pitchName,configuredInstrument} from './data.js';
import {staff} from './notation.js';
import {valveBindings,shortcutForValve,keyboardAction,validateBindings} from './keyboard.js';
import {woodwindChart,updateWoodwindChart,holeStates,cycleHole} from './woodwinds.js';
import {makeQueue,poolFor,choicesFor,newRound,submit,advance,accuracy,reveal,distinctMissed,missedPracticeQueue} from './engine.js';
const app=document.querySelector('#app');
let preferenceStorage;try{preferenceStorage=localStorage;}catch{}
let preferences=applyPreferences(loadPreferences(preferenceStorage),document.documentElement);
let config={instrument:'clarinet',tier:1,mode:'challenge',count:10,notation:'bass',valves:3,keyboard:true,attachment:false,alternates:DEFAULT_ALTERNATES,custom:null,maps:{},roundType:'questions',duration:60,customTime:false,hornType:'double'};
let answerView=null;
let round=null,choices=[],selection={keys:[]},timer=null,screen='setup',practice=false;
let roundClock=null,clockTick=null,roundPool=[],settingsDraft=false,savedConfig=null,settingsSheet=null,advanceRemaining=null,advanceAt=null;
try{config.maps=JSON.parse(localStorage.getItem('band-valve-maps')||'{}');}catch{}
const inst=()=>withAlternates(configuredInstrument(config.instrument,config.notation,config.valves,config.attachment,config.hornType),config.alternates);
const mapId=()=>config.instrument+':'+config.valves;
const mapping=()=>config.maps[mapId()];
const activePool=()=>practicePool(inst(),config.custom||defaultPractice(inst()));
const canStart=()=>activePool().length>0&&(config.roundType!=='timed'||validTimeLimit(config.duration));
const practiceTitle=()=>config.custom?.preset==='first'?'First notes':config.custom?.preset==='building'?'Build your range':config.custom?.preset==='chromatic'?'Chromatic fluency':config.custom?.preset==='full'?'Full verified range':config.custom?.preset==='extremes'?'Extended range':'Customized practice';
// Brass questions check valves or slide positions only.
const partials=()=>false;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
const choiceLabel=(i,j)=>i.kind==='valves'?'ABCD'[j]:j+1;
const valveHint=i=>valveBindings(i,mapping()).map(([key,id])=>key.toUpperCase()+' = '+(id==='Bb'?'trigger':'valve '+id.slice(1))).join(' · ');
const gearIcon=()=>{const points=Array.from({length:32},(_,j)=>{const a=(j+.5)*Math.PI/16,r=[27,27,22,22][j%4];return `${32+Math.cos(a)*r},${32+Math.sin(a)*r}`;});return `<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M${points.join(' L')}Z" fill="none" stroke="currentColor" stroke-width="4" stroke-linejoin="round"/><circle cx="32" cy="32" r="9" fill="none" stroke="currentColor" stroke-width="4"/></svg>`;};
const announce=s=>{document.querySelector('#announcement').textContent=s;};
function captions(f,i=inst(),showPartial=partials()){
 return fingeringCaption(f,i)+(showPartial&&f.partial?' · Partial '+f.partial:'');
}
function diagram(f,i=inst()){
 return i.kind==='woodwind'?woodwindChart(i,f):brassDiagram(f,i);
}
function customizer(i){
 const c=config.custom,notes=[...new Map(i.notes.map(n=>[n.midi,n])).values()],low=notes.find(n=>n.midi===c.low)||notes[0],high=notes.find(n=>n.midi===c.high)||notes.at(-1);
 const boundary=(side,n)=>`<div class="range-boundary"><span>${side==='low'?'Lowest note':'Highest note'}</span>${staff(n.pitch,i.clef)}<div class="range-step"><button type="button" data-step="${side}:-1" aria-label="Lower ${side==='low'?'lowest':'highest'} note">−</button><select id="range-${side}" aria-label="${side==='low'?'Lowest':'Highest'} note">${notes.map(x=>`<option value="${x.midi}" ${x.midi===c[side]?'selected':''}>${pitchName(x.pitch)}</option>`).join('')}</select><button type="button" data-step="${side}:1" aria-label="Raise ${side==='low'?'lowest':'highest'} note">+</button></div><input type="range" id="slider-${side}" aria-label="Drag ${side==='low'?'lowest':'highest'} note" min="0" max="${notes.length-1}" value="${notes.indexOf(n)}"></div>`;
 return `<label for="preset">Note Selection Presets</label><select id="preset">${[['first','First notes'],['building','Build your range'],['chromatic','Chromatic fluency'],['full','Full verified range'],['extremes',i.id.includes('sax')?'Range extremes · low C & below / high D & above':'Extended range'],['custom','Customized']].map(([id,label])=>`<option value="${id}" ${c.preset===id?'selected':''}>${label}</option>`).join('')}</select>${c.preset==='extremes'?'<p class="preset-explanation">Only the low and high extremes are selected. Middle notes are unchecked in Note filter; the boundary displays show the overall span.</p>':c.preset==='full'?'<p class="preset-explanation">Every supported note across the full range is selected.</p>':''}<div class="range-customizer">${boundary('low',low)}${boundary('high',high)}</div>${i.id==='trombone'?`<label class="check-setting"><input type="checkbox" id="attachment" ${config.attachment?'checked':''}> Use F-attachment trigger</label>`:''}<label class="check-setting"><input type="checkbox" id="chromatic" ${c.chromatic?'checked':''}> Include chromatic notes</label><div class="accidental-filters">${[['naturals','Naturals'],['sharps','Sharps ♯'],['flats','Flats ♭']].map(([id,label])=>`<label><input data-accidental="${id}" type="checkbox" ${c[id]?'checked':''} > ${label}</label>`).join('')}</div><details id="note-filter" class="note-filter"><summary>Note filter · ${activePool().length} selected</summary><p class="setting-help">Uncheck any written note to leave it out of practice.</p><div class="filter-actions"><button id="all-notes" type="button">Select all in range</button><button id="no-notes" type="button">Clear selection</button></div><div class="note-checks">${rangeNotes(i,c).map(n=>{const disabled=!noteAllowed(i,n,c);return `<label class="${disabled?'muted-note':''}"><input type="checkbox" data-note="${n.id}" ${!disabled&&!c.excluded.includes(n.id)?'checked':''} ${disabled?'disabled':''}> ${pitchName(n.pitch)}</label>`;}).join('')}</div></details><p class="range-line" id="pool-summary">${activePool().length} written notes · ${rangeText(activePool())}</p>`;
}
function bindCustomizer(root=app,onRefresh=setup){
 const app=root;
 const refresh=(focus,details=false)=>{const y=window.scrollY;onRefresh();if(details)app.querySelector('.note-filter').open=true;if(focus)app.querySelector(focus)?.focus({preventScroll:true});window.scrollTo(0,y);};
 const notes=[...new Map(inst().notes.map(n=>[n.midi,n])).values()];
 const setBoundary=(side,value,focus)=>{config.custom[side]=value;if(side==='low'&&value>config.custom.high)config.custom.high=value;if(side==='high'&&value<config.custom.low)config.custom.low=value;config.custom.preset='custom';config.custom.excluded=[];refresh(focus);};
 app.querySelector('#preset').onchange=e=>{config.custom=defaultPractice(inst(),e.target.value,config.custom?.key);refresh('#preset');};
 for(const side of ['low','high']){
  app.querySelector('#range-'+side).onchange=e=>setBoundary(side,+e.target.value,'#range-'+side);
  const slider=app.querySelector('#slider-'+side);
  slider.oninput=e=>{
   const value=notes[+e.target.value].midi;config.custom[side]=value;
   if(side==='low'&&value>config.custom.high)config.custom.high=value;
   if(side==='high'&&value<config.custom.low)config.custom.low=value;
   config.custom.preset='custom';config.custom.excluded=[];app.querySelector('#preset').value='custom';
   for(const boundary of ['low','high']){const note=notes.find(n=>n.midi===config.custom[boundary]);const select=app.querySelector('#range-'+boundary);select.value=String(note.midi);select.closest('.range-boundary').querySelector('.staff').outerHTML=staff(note.pitch,inst().clef);app.querySelector('#slider-'+boundary).value=notes.indexOf(note);}
   const pool=activePool();app.querySelector('#pool-summary').textContent=pool.length+' written notes · '+rangeText(pool);app.querySelector('#start').disabled=!canStart();
  };
  slider.onchange=()=>refresh('#slider-'+side);
 }
 app.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const[side,step]=b.dataset.step.split(':');const at=notes.findIndex(n=>n.midi===config.custom[side]);setBoundary(side,notes[Math.max(0,Math.min(notes.length-1,at+Number(step)))].midi,`[data-step="${b.dataset.step}"]`);});
 app.querySelector('#chromatic').onchange=e=>{config.custom.chromatic=e.target.checked;config.custom.preset='custom';refresh('#chromatic');};
 app.querySelectorAll('[data-accidental]').forEach(b=>b.onchange=()=>{config.custom[b.dataset.accidental]=b.checked;config.custom.preset='custom';refresh(`[data-accidental="${b.dataset.accidental}"]`);});
 app.querySelectorAll('[data-note]').forEach(b=>b.onchange=()=>{config.custom.excluded=config.custom.excluded.filter(x=>x!==b.dataset.note);if(!b.checked)config.custom.excluded.push(b.dataset.note);config.custom.preset='custom';refresh(`[data-note="${b.dataset.note}"]`,true);});
 app.querySelector('#all-notes').onclick=()=>{config.custom.excluded=[];config.custom.preset='custom';refresh('#all-notes',true);};
 app.querySelector('#no-notes').onclick=()=>{config.custom.excluded=inst().notes.map(n=>n.id);config.custom.preset='custom';refresh('#no-notes',true);};
}
function shortcutFields(){
 const i=inst(),rows=valveBindings(i,mapping());
 if(!rows.length)return '<p class="setting-help">Valve shortcuts are available for trumpet, horn, euphonium/baritone, and tuba. In Multiple Choice, use 1–4 to choose a diagram. Use Tab and Space to select woodwind keys.</p>';
 return `<form class="binding-form"><p class="setting-help">These valve keys apply to Build the Combination. Press once to select, again to release. Enter checks your answer. A–D select the four answer choices.</p><label class="check-setting"><input type="checkbox" class="shortcut-enabled" ${config.keyboard?'checked':''}> Enable valve keyboard shortcuts</label><div class="binding-fields">${rows.map(([key,id])=>`<label>${esc(i.keys.find(k=>k.id===id).label)}<input data-binding="${id}" value="${esc(key)}" maxlength="1" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Shortcut for ${esc(i.keys.find(k=>k.id===id).label)}"></label>`).join('')}</div><p class="binding-message setting-help" role="status"></p><div class="filter-actions"><button type="button" class="default-bindings">Use defaults</button><button type="button" class="number-bindings">Use number keys</button><button type="submit" class="primary">Save shortcuts</button></div><p class="setting-help">Saved for this instrument and valve configuration. Share settings includes your saved shortcuts.</p></form>`;
}
function commitShortcuts(container,report=true){
 const form=container.querySelector('.binding-form');if(!form)return true;
 const values=Object.fromEntries([...form.querySelectorAll('[data-binding]')].map(b=>[b.dataset.binding,b.value.toLowerCase()]));
 const error=validateBindings(values);if(report)form.querySelector('.binding-message').textContent=error||'Shortcuts saved.';
 if(error)return false;
 config.maps[mapId()]=values;config.keyboard=form.querySelector('.shortcut-enabled').checked;
 if(!settingsDraft){try{localStorage.setItem('band-valve-maps',JSON.stringify(config.maps));}catch{}}
 return true;
}
function bindShortcuts(container,onSave=()=>{}){
 const i=inst(),rows=valveBindings(i,mapping()),form=container.querySelector('.binding-form');if(!form)return;
 const save=()=>commitShortcuts(container,false);
 form.querySelectorAll('[data-binding]').forEach(input=>{input.onkeydown=e=>{if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();input.value=e.key.toLowerCase();save();}};input.oninput=save;});
 form.querySelector('.shortcut-enabled').onchange=save;
 form.querySelector('.default-bindings').onclick=()=>{valveBindings(i).forEach(([key,id])=>form.querySelector(`[data-binding="${id}"]`).value=key);commitShortcuts(container);};
 form.querySelector('.number-bindings').onclick=()=>{rows.forEach(([,id])=>form.querySelector(`[data-binding="${id}"]`).value=id==='Bb'?'x':id.slice(1));commitShortcuts(container);};
 form.onsubmit=e=>{e.preventDefault();if(commitShortcuts(container))onSave();};
}
function advancedFields(){
 const volume=(id,label,value)=>`<div class="sound-volume"><label for="${id}">${label}</label><div><input id="${id}" type="range" min="0" max="100" step="1" value="${Math.round(value*100)}" aria-valuetext="${Math.round(value*100)} percent"><output for="${id}" id="${id}-value">${Math.round(value*100)}%</output></div></div>`;
 return `<p class="setting-help">Preferences are saved on this device immediately.</p><section class="preference-section" aria-label="Appearance"><h3>Appearance</h3><span class="label">Accent color</span><div class="accent-options">${Object.entries(accentPresets).map(([id,p])=>`<label><input type="radio" name="accent" value="${id}" ${preferences.accent===id?'checked':''}><span class="accent-swatch" style="--swatch:${p.light}"></span>${p.name}</label>`).join('')}</div><label class="check-setting"><input id="dark-mode" type="checkbox" ${preferences.dark?'checked':''}> Dark mode</label><label for="preferred-chart-size">Chart size</label><select id="preferred-chart-size"><option value="standard" ${preferences.chartSize==='standard'?'selected':''}>Standard</option><option value="large" ${preferences.chartSize==='large'?'selected':''}>Large</option></select></section><section class="preference-section" aria-label="Sound"><h3>Sound</h3>${volume('note-volume','Note volume',preferences.noteVolume)}${volume('wrong-volume','Incorrect-answer volume',preferences.wrongVolume)}<label class="check-setting"><input id="correct-sound" type="checkbox" ${preferences.correctSound?'checked':''}> Play sound for correct answers</label><label class="check-setting"><input id="wrong-sound" type="checkbox" ${preferences.wrongSound?'checked':''}> Play sound for incorrect answers</label><p class="setting-help">The correct-answer toggle controls automatic answer tones. Hear Tone is always available and uses the note volume.</p><button id="restore-sound-defaults" type="button">Restore sound defaults</button><p id="sound-settings-status" class="setting-help" role="status"></p></section>`;
}
function syncChartSize(){
 const workbench=app.querySelector('.woodwind-workbench');if(!workbench)return;
 const large=preferences.chartSize==='large';workbench.classList.toggle('enlarged',large);
 const button=workbench.querySelector('#chart-size');if(button){button.textContent=large?'Compact chart':'Enlarge chart';button.setAttribute('aria-expanded',String(large));}
}
function bindAdvanced(root){
 const save=()=>{
  const previousSize=preferences.chartSize;
  preferences=applyPreferences({...preferences,accent:root.querySelector('[name="accent"]:checked').value,dark:root.querySelector('#dark-mode').checked,chartSize:root.querySelector('#preferred-chart-size').value,noteVolume:+root.querySelector('#note-volume').value/100,wrongVolume:+root.querySelector('#wrong-volume').value/100,correctSound:root.querySelector('#correct-sound').checked,wrongSound:root.querySelector('#wrong-sound').checked},document.documentElement,preferenceStorage);
  for(const id of ['note-volume','wrong-volume']){const value=root.querySelector('#'+id).value;root.querySelector('#'+id+'-value').textContent=value+'%';root.querySelector('#'+id).setAttribute('aria-valuetext',value+' percent');}
  if(previousSize!==preferences.chartSize)syncChartSize();
  root.querySelector('#sound-settings-status').textContent='';
 };
 root.querySelectorAll('[name="accent"],#dark-mode,#preferred-chart-size,#correct-sound,#wrong-sound').forEach(input=>input.onchange=save);
 root.querySelectorAll('#note-volume,#wrong-volume').forEach(input=>input.oninput=save);
 root.querySelector('#restore-sound-defaults').onclick=()=>{
  preferences=applyPreferences(restoreSoundDefaults(preferences),document.documentElement,preferenceStorage);
  for(const [id,value]of [['note-volume',preferences.noteVolume],['wrong-volume',preferences.wrongVolume]]){const percent=Math.round(value*100);root.querySelector('#'+id).value=percent;root.querySelector('#'+id).setAttribute('aria-valuetext',percent+' percent');root.querySelector('#'+id+'-value').textContent=percent+'%';}
  root.querySelector('#correct-sound').checked=preferences.correctSound;root.querySelector('#wrong-sound').checked=preferences.wrongSound;
  root.querySelector('#sound-settings-status').textContent='Sound defaults restored.';
 };
}
function openPracticeSettings(){
 if(settingsDraft)return;
 if(advanceAt!==null)advanceRemaining=Math.max(0,advanceAt-performance.now());advanceAt=null;clearTimeout(timer);pauseClock(roundClock,performance.now());settingsDraft=true;savedConfig=structuredClone(config);config=structuredClone(config);
 let dialog=document.querySelector('#practice-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='practice-dialog';dialog.setAttribute('aria-label','Practice Settings');document.body.append(dialog);}
 dialog.oncancel=e=>{e.preventDefault();closePracticeSettings(false);};
 dialog.onclick=e=>{if(e.target===dialog)closePracticeSettings(false);};
 settingsSheet=null;renderPracticeDialog();dialog.showModal();
}
const sheetNames={instrument:'Instrument',mode:'Game mode',notes:'Notes & range',keyboard:'Keyboard shortcuts',round:'Round & timing',advanced:'Appearance & Sound'};
function showSettingsSheet(id,animate=true){
 const dialog=document.querySelector('#practice-dialog'),back=id===null;settingsSheet=id;
 dialog.querySelector('#sheet-title').textContent=id?sheetNames[id]:'Practice Settings';
 dialog.querySelector('#settings-back').hidden=back;
 for(const page of dialog.querySelectorAll('[data-sheet]')){const visible=page.dataset.sheet===(id||'menu');page.hidden=!visible;page.classList.remove('sheet-forward','sheet-back');if(visible){if(animate)page.classList.add(back?'sheet-back':'sheet-forward');page.scrollTop=0;}}
 if(animate){if(back)dialog.querySelector('[data-open-sheet]')?.focus({preventScroll:true});else dialog.querySelector('#settings-back').focus({preventScroll:true});}
}
function renderPracticeDialog(){
 const dialog=document.querySelector('#practice-dialog'),open=[...dialog.querySelectorAll('details[open]')].map(d=>d.id).filter(Boolean),scroll=dialog.querySelector('[data-sheet]:not([hidden])')?.scrollTop||0;
 if(!config.custom)config.custom=defaultPractice(inst());
 const summaries={instrument:inst().name,mode:config.mode==='challenge'?'Multiple Choice':'Build the Combination',notes:practiceTitle(),keyboard:inst().kind==='valves'?'Valve mappings':'Input help',advanced:preferences.dark?'Dark mode':'Light mode',round:config.roundType==='timed'?formatTime(config.duration*1000)+' timed':config.count+' questions'};
 dialog.innerHTML=`<div class="floating-settings-head"><button id="settings-back" class="text-button" aria-label="Back to Practice Settings">‹ Back</button><h2 id="sheet-title">Practice Settings</h2><button id="close-settings" aria-label="Close settings">×</button></div><div class="settings-sheets settings"><section class="sheet-page settings-menu" data-sheet="menu">${Object.entries(sheetNames).map(([id,title])=>`<button class="sheet-menu-item" data-open-sheet="${id}"><span>${title}<small>${esc(summaries[id])}</small></span><span aria-hidden="true">›</span></button>`).join('')}<button id="share-settings" class="share-settings" type="button">Share settings</button><p id="share-status" class="setting-help" role="status"></p></section>${practiceFields(inst(),true)}</div><div class="floating-settings-footer"><p>Play is paused. Apply changes starts a new round.</p><div><button id="cancel-settings">Cancel</button><button id="start" class="primary" ${canStart()?'':'disabled'}>Apply changes</button></div></div>`;
 for(const id of open){const details=dialog.querySelector('#'+id);if(details)details.open=true;}
 bindPracticeFields(dialog,renderPracticeDialog,()=>closePracticeSettings(true));
 dialog.querySelectorAll('[data-open-sheet]').forEach(b=>b.onclick=()=>showSettingsSheet(b.dataset.openSheet));
 dialog.querySelector('#settings-back').onclick=()=>showSettingsSheet(null);
 dialog.querySelector('#close-settings').onclick=dialog.querySelector('#cancel-settings').onclick=()=>closePracticeSettings(false);
 showSettingsSheet(settingsSheet,false);dialog.querySelector('[data-sheet]:not([hidden])').scrollTop=scroll;
}
function closePracticeSettings(apply){
 const dialog=document.querySelector('#practice-dialog');
 if(apply){
  const form=dialog.querySelector('.binding-form');
  if(form){const values=Object.fromEntries([...form.querySelectorAll('[data-binding]')].map(b=>[b.dataset.binding,b.value.toLowerCase()]));const error=validateBindings(values);if(error){showSettingsSheet('keyboard');form.querySelector('.binding-message').textContent=error;return;}if(valveBindings(inst(),mapping()).some(([key,id])=>key!==values[id]))config.maps[mapId()]=values;config.keyboard=form.querySelector('.shortcut-enabled').checked;}
  if(!canStart())return;
 }
 const changed=apply&&JSON.stringify(config)!==JSON.stringify(savedConfig);
 if(!apply)config=savedConfig;
 settingsDraft=false;savedConfig=null;dialog.close();
 if(changed){try{localStorage.setItem('band-valve-maps',JSON.stringify(config.maps));}catch{}start();}
 else{resumeClock(roundClock,performance.now());updateClock();if(round.solved&&advanceRemaining!==null)scheduleAdvance(advanceRemaining);}
}
async function shareSettings(root=app){
 const app=root;
 const url=settingsUrl(location.href,config),status=app.querySelector('#share-status');
 const local=location.protocol==='file:'||['localhost','127.0.0.1','::1','[::1]'].includes(location.hostname);
 const note=local?' This copy is local to your computer. Open the hosted website to copy a link students can use.':'';
 try{await navigator.clipboard.writeText(url);status.textContent='Settings link copied!'+note;const preview=document.createElement('a');preview.href=url;preview.textContent='Preview shared settings';preview.className='shared-preview';status.append(preview);}
 catch{status.textContent='Copy this settings link:'+note;const field=document.createElement('textarea');field.readOnly=true;field.value=url;field.className='share-link';field.setAttribute('aria-label','Settings link');status.append(field);field.focus();field.select();}
}

function settingsTopic(id,title,content,floating){return floating?`<section class="sheet-page" data-sheet="${id}" hidden>${content}</section>`:`<section class="settings-block" data-topic="${id}" ${advancedTopic!==id?'hidden':''}><h2>${title}</h2>${content}</section>`;}
function practiceFields(i,floating=false){
 const instrument=`${i.id==='horn'?`<label class="check-setting"><input type="checkbox" id="horn-double" ${config.hornType!=='single'?'checked':''}> Double horn · show thumb trigger</label><p class="setting-help">Uncheck for F single horn. Only F-side fingerings will be accepted.</p>`:''}${['euphonium','tuba'].includes(i.id)?`<label for="valve-count">Instrument valves</label><select id="valve-count"><option value="3" ${config.valves===3?'selected':''}>3 valves</option><option value="4" ${config.valves===4?'selected':''}>4 valves</option></select>`:''}${i.id==='euphonium'?`<label for="notation">Part notation</label><select id="notation"><option value="bass" ${config.notation==='bass'?'selected':''}>Bass clef · concert pitch</option><option value="treble" ${config.notation==='treble'?'selected':''}>B♭ treble clef</option></select>`:''}`;
 const chooseInstrument=`<label for="settings-instrument">Instrument</label><select id="settings-instrument">${instruments.map(x=>`<option value="${x.id}" ${x.id===config.instrument?'selected':''}>${x.name}</option>`).join('')}</select>`;
 const hornKey=i.id==='horn'?`<label for="concert-key">Beginning concert key</label><select id="concert-key"><option value="Bb" ${config.custom.key!=='F'?'selected':''}>Concert B♭ major</option><option value="F" ${config.custom.key==='F'?'selected':''}>Concert F major</option></select>`:'';
 const timing=`<label for="round-type">Round type</label><select id="round-type"><option value="questions" ${config.roundType!=='timed'?'selected':''}>Question round</option><option value="timed" ${config.roundType==='timed'?'selected':''}>Timed challenge</option></select>${config.roundType==='timed'?`<label for="duration">Time limit</label><select id="duration">${[30,60,120,180,300].map(n=>`<option value="${n}" ${!config.customTime&&config.duration===n?'selected':''}>${formatTime(n*1000)}</option>`).join('')}<option value="custom" ${config.customTime?'selected':''}>Custom Time</option></select>${config.customTime?`<label for="custom-time">Custom time (mm:ss)</label><input id="custom-time" inputmode="text" maxlength="5" placeholder="01:30" value="${validTimeLimit(config.duration)?formatTime(config.duration*1000).padStart(5,'0'):''}" aria-describedby="time-help"><p id="time-help" class="setting-help">Enter 00:01 through 99:59.</p>`:''}<p class="setting-help">Answer as many notes correctly as you can before time runs out. Revealed answers do not score.</p>`:`<label for="question-count">Questions</label><select id="question-count">${[10,20,30].map(n=>`<option value="${n}" ${config.count===n?'selected':''}>${n}</option>`).join('')}</select>`}`;
 return settingsTopic('instrument','Instrument & equipment',chooseInstrument+instrument,floating)+settingsTopic('mode','Game mode',`<span class="label">Game mode</span><div class="mode-options">${[['challenge','Multiple Choice','Choose the correct diagram from four options.'],['interactive','Build the Combination','Build the fingering, then check your answer.']].map(([id,title,desc])=>`<button class="mode ${config.mode===id?'active':''}" data-mode="${id}" aria-pressed="${config.mode===id}">${title}<span>${desc}</span></button>`).join('')}</div>`,floating)+settingsTopic('notes','Notes & range',hornKey+customizer(i)+`<label class="check-setting"><input id="alternates" type="checkbox" ${config.alternates?'checked':''}> Accept alternate fingerings</label><p class="setting-help">${config.alternates?'All documented alternatives are accepted.':'Practice the primary chart fingering only.'}</p>`,floating)+(floating?settingsTopic('keyboard','Keyboard shortcuts',shortcutFields(),true):settingsTopic('keyboard','Keyboard shortcuts',`<div id="keyboard-shortcuts">${shortcutFields()}</div>`,false))+settingsTopic('round','Round & timing',timing,floating)+settingsTopic('advanced','Appearance & Sound',advancedFields(),floating)+(floating?'':settingsTopic('share','Share settings',`<p class="setting-help">Copy your practice settings as a link.</p><button id="share-settings" class="share-settings" type="button">Share settings</button><p id="share-status" class="setting-help" role="status"></p>`,false));
}
function bindPracticeFields(root,refresh,onStart){
 const app=root;
 app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{config.mode=b.dataset.mode;refresh();});
 app.querySelector('#question-count')?.addEventListener('change',e=>{config.count=+e.target.value;refresh();});
 app.querySelectorAll('[data-count]').forEach(b=>b.onclick=()=>{config.count=+b.dataset.count;refresh();});
 bindCustomizer(root,refresh);bindShortcuts(root);bindAdvanced(root);app.querySelector('#share-settings').onclick=()=>{if(commitShortcuts(root))shareSettings(root);};
 app.querySelector('#alternates').onchange=e=>{config.alternates=e.target.checked;refresh();};
 for(const [id,field,convert] of [['horn-double','hornType',e=>e.target.checked?'double':'single'],['attachment','attachment',e=>e.target.checked],['notation','notation',e=>e.target.value],['valve-count','valves',e=>+e.target.value],['settings-instrument','instrument',e=>e.target.value]])app.querySelector('#'+id)?.addEventListener('change',e=>{config[field]=convert(e);config.custom=null;refresh();});
 app.querySelector('#concert-key')?.addEventListener('change',e=>{config.custom=defaultPractice(inst(),config.custom.preset,e.target.value);refresh();});
 app.querySelector('#round-type').onchange=e=>{config.roundType=e.target.value;refresh();};
 app.querySelector('#duration')?.addEventListener('change',e=>{config.customTime=e.target.value==='custom';if(!config.customTime)config.duration=+e.target.value;refresh();});
 app.querySelector('#custom-time')?.addEventListener('input',e=>{config.duration=parseTimeLimit(e.target.value)||0;const valid=validTimeLimit(config.duration);e.target.setAttribute('aria-invalid',String(!valid));app.querySelector('#time-help').textContent=valid?'Custom time: '+formatTime(config.duration*1000):'Enter a time from 00:01 through 99:59 (mm:ss).';app.querySelector('#start').disabled=!canStart();app.querySelector('#share-settings').disabled=!canStart();});
 app.querySelector('#start').onclick=()=>{if(commitShortcuts(root))onStart();};
}
let page='home',instrumentChosen=false,advancedTopic='notes',referencePitch=null,referenceAlternate=0,referenceInstrument=null,modalPause=false;
const levelName=()=>studentLevels.find(l=>l.id===studentLevel(inst(),config.custom||defaultPractice(inst())))?.name||'Custom';
function updateNavigation(){const current=screen==='play'||screen==='results'?'practice':page;document.querySelectorAll('[data-page]').forEach(b=>{const active=b.dataset.page===current;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const label=bannerInstrumentName({screen,page,instrumentChosen,instrument:inst(),libraryInstrument:instruments.find(i=>i.id===referenceInstrument)}),pill=document.querySelector('#header-instrument');if(pill.textContent!==label)pill.textContent=label;}
function navigate(target){
 if(screen==='play'){if(target==='advanced'){openPracticeSettings();return;}if(target==='references'){openNoteLibrary();return;}if(target==='practice')return;}
 clearTimeout(timer);clearInterval(clockTick);if(roundClock)pauseClock(roundClock,performance.now());screen='setup';page=target;
 if(target==='references'&&referenceInstrument!==config.instrument){referenceInstrument=config.instrument;referencePitch=null;referenceAlternate=0;}
 if(target==='practice'&&!instrumentChosen){page='home';renderHome();announce('Choose your instrument first.');return;}
 if(target==='home')renderHome();else if(target==='practice')renderPractice();else if(target==='references')renderReferences();else renderAdvancedSetup();
 updateNavigation();window.scrollTo({top:0,behavior:'instant'});
}
function chooseInstrument(id){if(config.instrument!==id){const level=studentLevel(inst(),config.custom||defaultPractice(inst()));config.instrument=id;config.custom=studentPreset(inst(),level==='custom'?'beginner':level,config.custom?.key)||defaultPractice(inst());referencePitch=null;referenceInstrument=id;}instrumentChosen=true;}
function equipmentFields(prefix=''){
 const i=inst(),id=s=>prefix+s;
 return `${i.id==='horn'?`<label for="${id('horn-type')}">Your horn</label><select id="${id('horn-type')}"><option value="single" ${config.hornType==='single'?'selected':''}>F single horn</option><option value="double" ${config.hornType!=='single'?'selected':''}>Double horn · thumb trigger</option></select>`:''}${i.id==='trombone'?`<label class="check-setting"><input type="checkbox" id="${id('attachment')}" ${config.attachment?'checked':''}> My trombone has a trigger</label>`:''}${['euphonium','tuba'].includes(i.id)?`<label for="${id('valve-count')}">How many valves?</label><select id="${id('valve-count')}"><option value="3" ${config.valves===3?'selected':''}>3 valves</option><option value="4" ${config.valves===4?'selected':''}>4 valves</option></select>`:''}${i.id==='euphonium'?`<label for="${id('notation')}">Your music</label><select id="${id('notation')}"><option value="bass" ${config.notation==='bass'?'selected':''}>Bass clef</option><option value="treble" ${config.notation==='treble'?'selected':''}>B♭ treble clef</option></select>`:''}`;
}
function bindEquipment(root,prefix,refresh){for(const [id,field,read]of [['horn-type','hornType',e=>e.target.value],['attachment','attachment',e=>e.target.checked],['valve-count','valves',e=>+e.target.value],['notation','notation',e=>e.target.value]])root.querySelector('#'+prefix+id)?.addEventListener('change',e=>{const previous=studentLevel(inst(),config.custom||defaultPractice(inst())),old=config.custom;config[field]=read(e);config.custom=studentPreset(inst(),previous,old?.key)||defaultPractice(inst(),'custom',old?.key);refresh();});}
function renderHome(){
 page='home';screen='setup';if(!config.custom)config.custom=defaultPractice(inst());const i=inst();
 app.innerHTML=`<section class="welcome-banner"><div><p class="eyebrow">READ. CONNECT. PLAY.</p><h1>Find Notes. Build Skills. Go Further.</h1><p>Master your instrument, one note at a time.</p></div><div class="hero-notes" aria-hidden="true">♫ <span>♪</span></div></section><div class="home-layout"><section class="instrument-picker panel"><div class="section-heading"><div><p class="step-label">STEP 1</p><h2>What instrument do you play?</h2></div></div><div class="photo-instrument-grid">${instruments.map(x=>`<button class="photo-instrument ${instrumentChosen&&x.id===i.id?'selected':''}" data-instrument="${x.id}" aria-pressed="${instrumentChosen&&x.id===i.id}">${silhouetteImage(x)}<span>${x.name}</span>${instrumentChosen&&x.id===i.id?'<span class="selected-tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div></section><aside class="instrument-ready panel settings">${instrumentChosen?`<p class="step-label">YOUR INSTRUMENT</p>${silhouetteImage(i,'selected-photo')}<h2>${i.name}</h2>${equipmentFields('home-')}<p class="setting-help">Ready? Choose a level next.</p><button id="choose-level" class="primary start">Choose your level ${uiIcon('arrow')}</button>`:`<div class="ready-symbol">${uiIcon('book')}</div><h2>Your quest starts here.</h2><p class="subtle">Choose your instrument, then take it one note at a time.</p><p class="setting-help">Not sure? Ask your band director or explore the references.</p><button id="home-reference">Explore Note Library ${uiIcon('arrow')}</button>`}</aside></div><footer>Made for practice. No login or microphone needed.</footer>`;
 app.querySelectorAll('[data-instrument]').forEach(b=>b.onclick=()=>{chooseInstrument(b.dataset.instrument);renderHome();app.querySelector('#choose-level')?.focus({preventScroll:true});});bindEquipment(app,'home-',renderHome);app.querySelector('#choose-level')?.addEventListener('click',()=>navigate('practice'));app.querySelector('#home-reference')?.addEventListener('click',()=>navigate('references'));updateNavigation();
}
function compactSummary(){const i=inst();return `<div class="practice-summary">${silhouetteImage(i,'summary-photo')}<div><strong>${i.name}</strong><span>${esc(i.system)} · ${levelName()} · ${config.roundType==='timed'?formatTime(config.duration*1000)+' timed':config.count+' questions'}</span></div><button class="text-button" data-change-instrument>Change instrument</button></div>`;}
function renderPractice(){
 page='practice';screen='setup';if(!config.custom)config.custom=defaultPractice(inst());const selected=studentLevel(inst(),config.custom);
 app.innerHTML=`<div class="page-heading"><div><p class="step-label">STEP 2</p><h1>Make it your practice.</h1><p class="subtle">Choose a level, then choose how you want to play.</p></div><button id="practice-advanced" class="text-button">Advanced Setup ${uiIcon('sliders')}</button></div>${compactSummary()}<section class="level-section"><h2>Choose your level</h2><div class="level-cards">${studentLevels.map(l=>`<button class="level-card ${selected===l.id?'active':''}" data-level="${l.id}" aria-pressed="${selected===l.id}"><span class="level-number">${l.number}</span><strong>${l.name}</strong><span>${l.description}</span></button>`).join('')}</div>${inst().id==='horn'&&selected==='beginner'?`<label class="beginner-key">Beginning concert key <select id="practice-concert-key"><option value="Bb" ${config.custom.key!=='F'?'selected':''}>Concert B♭ major</option><option value="F" ${config.custom.key==='F'?'selected':''}>Concert F major</option></select></label>`:''}</section><section class="mode-section"><p class="step-label">STEP 3</p><h2>How would you like to play?</h2><div class="student-modes">${[['challenge','Multiple Choice','Choose the correct fingering from four pictures.','choices'],['interactive','Build the Combination','Press the keys, valves, or slide position yourself.','keys']].map(([id,title,desc,icon])=>`<button class="student-mode ${config.mode===id?'active':''}" data-mode="${id}" aria-pressed="${config.mode===id}"><span class="mode-symbol">${uiIcon(icon)}</span><span><strong>${title}</strong><span>${desc}</span></span><span class="mode-radio" aria-hidden="true"></span></button>`).join('')}</div></section><section class="practice-round-options panel" aria-label="Round type"><h2>Choose your round</h2><div class="round-options"><div class="round-choice ${config.roundType!=='timed'?'active':''}"><label><input type="radio" name="student-round" data-round-type="questions" ${config.roundType!=='timed'?'checked':''}> Questions</label><select id="question-count" aria-label="Number of questions">${[10,20,30].map(n=>`<option value="${n}" ${config.count===n?'selected':''}>${n}</option>`).join('')}</select></div><div class="round-choice ${config.roundType==='timed'?'active':''}"><label><input type="radio" name="student-round" data-round-type="timed" ${config.roundType==='timed'?'checked':''}> Timed</label><select id="practice-duration" aria-label="Time limit">${[30,60,120,180,300].map(n=>`<option value="${n}" ${!config.customTime&&config.duration===n?'selected':''}>${n<60?n+' seconds':n/60+(n===60?' minute':' minutes')}</option>`).join('')}<option value="custom" ${config.customTime?'selected':''}>Custom Time</option></select></div></div>${config.roundType==='timed'&&config.customTime?`<label class="label" for="practice-custom-time">Custom time (mm:ss)</label><input id="practice-custom-time" inputmode="text" maxlength="5" placeholder="01:30" value="${validTimeLimit(config.duration)?formatTime(config.duration*1000).padStart(5,'0'):''}" aria-describedby="practice-time-help"><p id="practice-time-help" class="setting-help">Enter 00:01 through 99:59.</p>`:''}</section><div class="practice-start panel"><div class="practice-pool"><strong>${activePool().length} written notes</strong><span>${rangeText(activePool())}</span></div><button id="start" class="primary" ${canStart()?'':'disabled'}>Start Practice ${uiIcon('arrow')}</button></div>${!canStart()?'<p class="feedback bad">Choose some notes and a valid time in Advanced Setup before starting.</p>':''}<p id="shared-status" class="setting-help" role="status"></p>`;
 app.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(b.dataset.level==='custom'){advancedTopic='notes';navigate('advanced');return;}config.custom=studentPreset(inst(),b.dataset.level,config.custom.key);renderPractice();});app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{config.mode=b.dataset.mode;renderPractice();});app.querySelector('#question-count').onchange=e=>{config.count=+e.target.value;config.roundType='questions';renderPractice();};
 app.querySelectorAll('[data-round-type]').forEach(b=>b.onchange=()=>{config.roundType=b.dataset.roundType;renderPractice();});
 app.querySelector('#practice-duration').onchange=e=>{config.roundType='timed';config.customTime=e.target.value==='custom';if(!config.customTime)config.duration=+e.target.value;renderPractice();};
 app.querySelector('#practice-custom-time')?.addEventListener('input',e=>{config.duration=parseTimeLimit(e.target.value)||0;const valid=validTimeLimit(config.duration);e.target.setAttribute('aria-invalid',String(!valid));app.querySelector('#practice-time-help').textContent=valid?'Custom time: '+formatTime(config.duration*1000):'Enter 00:01 through 99:59 (mm:ss).';app.querySelector('#start').disabled=!canStart();});app.querySelector('#practice-concert-key')?.addEventListener('change',e=>{config.custom=studentPreset(inst(),'beginner',e.target.value);renderPractice();});app.querySelector('#practice-advanced').onclick=()=>navigate('advanced');app.querySelector('[data-change-instrument]').onclick=()=>navigate('home');app.querySelector('#change-timing')?.addEventListener('click',()=>{advancedTopic='round';navigate('advanced');});app.querySelector('#start').onclick=()=>start();updateNavigation();
}
const advancedTopics={instrument:'Instrument & equipment',notes:'Notes & range',mode:'Game mode',round:'Round & timing',keyboard:'Keyboard shortcuts',advanced:'Appearance & Sound',share:'Share settings'};
function renderAdvancedSetup(){
 page='advanced';screen='setup';instrumentChosen=true;if(!config.custom)config.custom=defaultPractice(inst());
 app.innerHTML=`<div class="page-heading"><div><p class="step-label">YOUR PRACTICE, YOUR WAY</p><h1>Advanced Setup</h1><p class="subtle">Choose exactly what you want to practice.</p></div><button id="back-practice" class="text-button">Back to Practice ${uiIcon('arrow')}</button></div><div class="advanced-workspace"><aside class="advanced-sidebar panel">${silhouetteImage(inst(),'workspace-photo')}<strong>${inst().name}</strong><nav aria-label="Advanced Setup topics">${Object.entries(advancedTopics).map(([id,name])=>`<button data-advanced-topic="${id}" class="${advancedTopic===id?'active':''}" ${advancedTopic===id?'aria-current="page"':''}>${uiIcon(id==='keyboard'?'keys':id==='mode'?'choices':'sliders')}<span>${name}</span></button>`).join('')}</nav></aside><section class="panel settings advanced-content">${practiceFields(inst())}<div class="advanced-footer"><p class="setting-help">${activePool().length} written notes · ${rangeText(activePool())}</p><button id="start" class="primary" ${canStart()?'':'disabled'}>Use these settings ${uiIcon('arrow')}</button></div></section></div>`;
 bindPracticeFields(app,renderAdvancedSetup,()=>navigate('practice'));app.querySelectorAll('[data-advanced-topic]').forEach(b=>b.onclick=()=>{if(!commitShortcuts(app)){advancedTopic='keyboard';app.querySelectorAll('[data-topic]').forEach(s=>s.hidden=s.dataset.topic!=='keyboard');return;}advancedTopic=b.dataset.advancedTopic;renderAdvancedSetup();});app.querySelector('#back-practice').onclick=()=>{if(commitShortcuts(app))navigate('practice');};updateNavigation();
}
function referenceSelection(){
 const i=configuredInstrument(referenceInstrument||config.instrument,config.notation,config.valves,config.attachment,config.hornType);
 const n=i.notes.find(n=>n.id===referencePitch)||i.notes.find(n=>n.id===activePool()[0]?.id)||i.notes[0];
 referencePitch=n.id;const fingerings=answerFingerings(n,true);referenceAlternate=Math.min(referenceAlternate,fingerings.length-1);
 return {i,n,fingerings,at:i.notes.indexOf(n)};
}
function referenceChartContent(i,n,fingerings){
 return `<div class="reference-diagram">${diagram(fingerings[referenceAlternate],i)}${fingerings.length>1?`<div class="answer-navigation"><button class="answer-arrow" id="reference-alt-prev" aria-label="Previous reference fingering">‹</button><button class="answer-arrow" id="reference-alt-next" aria-label="Next reference fingering">›</button></div>`:''}</div><p class="reference-variant" aria-live="polite">${referenceAlternate===0?'Main fingering':'Alternate '+referenceAlternate}${fingerings.length>1?' · '+(referenceAlternate+1)+' of '+fingerings.length:''}</p><p>${esc(captions(fingerings[referenceAlternate],i,false))}</p>${n.tip?`<p class="setting-help">${esc(n.tip)}</p>`:''}`;
}
function updateReferenceDisplay(container=app){
 const app=container;
 const {i,n,fingerings,at}=referenceSelection(),root=app.querySelector('#reference-staff');
 const template=document.createElement('div');template.innerHTML=staff(n.pitch,i.clef,true);
 const fresh=template.firstElementChild,svg=root.querySelector('.staff');
 // Keep the SVG and slider container mounted so pointer capture survives live updates.
 svg.innerHTML=fresh.innerHTML;svg.setAttribute('aria-label',fresh.getAttribute('aria-label'));
 root.setAttribute('aria-valuenow',at);root.setAttribute('aria-valuetext',pitchName(n.pitch));
 app.querySelector('#reference-note-name').textContent=pitchName(n.pitch);app.querySelector('#reference-note').value=n.id;
 app.querySelector('#reference-prev').disabled=at===0;app.querySelector('#reference-next').disabled=at===i.notes.length-1;
 app.querySelector('#reference-chart-body').innerHTML=referenceChartContent(i,n,fingerings);
 for(const [id,step]of [['reference-alt-prev',-1],['reference-alt-next',1]])app.querySelector('#'+id)?.addEventListener('click',()=>{referenceAlternate=nextAnswerIndex(referenceAlternate,step,fingerings.length);updateReferenceDisplay(app);});
}
function renderReferences(root=app,floating=false){
 const app=root;
 if(!floating){page='references';screen='setup';if(!referenceInstrument)referenceInstrument=config.instrument;}const {i,n,fingerings,at}=referenceSelection();
 app.innerHTML=`<div class="page-heading"><div><p class="step-label">LOOK. LISTEN. LEARN.</p>${floating?'':'<h1>Note Library</h1>'}<p class="subtle">Drag a written note to explore its fingering.</p></div><button id="reference-guide">Guides & Sources ${uiIcon('book')}</button></div><div class="reference-controls panel"><div class="reference-instrument">${silhouetteImage(i,'summary-photo')}<label for="reference-instrument">Instrument<select id="reference-instrument">${instruments.map(x=>`<option value="${x.id}" ${x.id===i.id?'selected':''}>${x.name}</option>`).join('')}</select></label></div><label for="reference-note">Written note<select id="reference-note">${i.notes.map(x=>`<option value="${x.id}" ${x.id===n.id?'selected':''}>${pitchName(x.pitch)}</option>`).join('')}</select></label><button id="reference-prev" aria-label="Previous reference note" ${at===0?'disabled':''}>←</button><button id="reference-next" aria-label="Next reference note" ${at===i.notes.length-1?'disabled':''}>→</button></div><div class="reference-layout"><section class="panel reference-note"><div id="reference-staff" tabindex="0" role="slider" aria-label="Written note: drag up or down, or use arrow keys" aria-orientation="vertical" aria-valuemin="0" aria-valuemax="${i.notes.length-1}" aria-valuenow="${at}" aria-valuetext="${pitchName(n.pitch)}">${staff(n.pitch,i.clef,true)}</div><p class="reference-drag-help">Drag the note up or down · ↑ ↓ keys also work</p><h2 id="reference-note-name">${pitchName(n.pitch)}</h2><p class="subtle">Written pitch · ${i.clef} clef</p><button id="reference-tone" class="primary">Hear Tone</button></section><section class="panel reference-chart" id="reference-chart-body">${referenceChartContent(i,n,fingerings)}</section></div>${fullChartSection(i)}`;
 const setNote=id=>{referencePitch=id;referenceAlternate=0;updateReferenceDisplay(app);};
 app.querySelector('#reference-instrument').onchange=e=>{referenceInstrument=e.target.value;referencePitch=null;referenceAlternate=0;renderReferences(app,floating);};
 app.querySelector('#reference-note').onchange=e=>setNote(e.target.value);
 app.querySelector('#reference-prev').onclick=()=>{const at=i.notes.findIndex(n=>n.id===referencePitch);if(at>0)setNote(i.notes[at-1].id);};
 app.querySelector('#reference-next').onclick=()=>{const at=i.notes.findIndex(n=>n.id===referencePitch);if(at<i.notes.length-1)setNote(i.notes[at+1].id);};
 app.querySelector('#reference-tone').onclick=()=>{const n=i.notes.find(n=>n.id===referencePitch);playNoteTone(n.midi,i.transpose,i.id,undefined,preferences.noteVolume);};app.querySelector('#reference-guide').onclick=()=>guide(i);
 bindReferenceDrag(app.querySelector('#reference-staff'),i,()=>i.notes.find(n=>n.id===referencePitch).pitch,setNote);
 bindFullChart(app.querySelector('.full-fingering-chart'),i,()=>referencePitch,id=>{setNote(id);const note=app.querySelector('#reference-staff');note.scrollIntoView({block:'center',behavior:'instant'});note.focus({preventScroll:true});});
 updateReferenceDisplay(app);if(!floating)updateNavigation();
}
function openNoteLibrary(){
 if(modalPause||settingsDraft)return;
 let dialog=document.querySelector('#library-dialog');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='library-dialog';dialog.setAttribute('aria-labelledby','library-title');document.body.append(dialog);}
 referenceInstrument=config.instrument;referencePitch=round.queue[round.index].id;referenceAlternate=0;
 dialog.innerHTML=`<div class="dialog-head"><h2 id="library-title">Note Library</h2><button id="close-library" aria-label="Return to current question">×</button></div><p class="setting-help">Your round is paused. Close the library to return to the same question.</p><div class="library-content"></div>`;
 dialog.querySelector('#close-library').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};
 renderReferences(dialog.querySelector('.library-content'),true);pauseForModal(dialog);dialog.showModal();
}
function setup(){navigate('practice');}
function pauseForModal(dialog){if(screen!=='play'||modalPause)return;modalPause=true;if(advanceAt!==null)advanceRemaining=Math.max(0,advanceAt-performance.now());advanceAt=null;clearTimeout(timer);pauseClock(roundClock,performance.now());const current=round;dialog.addEventListener('close',()=>{modalPause=false;if(screen==='play'&&round===current){resumeClock(roundClock,performance.now());updateClock();if(round.solved&&advanceRemaining!==null)scheduleAdvance(advanceRemaining);}},{once:true});}

function rangeText(notes){if(!notes.length)return 'No notes selected';const sorted=[...notes].sort((a,b)=>a.midi-b.midi);return pitchName(sorted[0].pitch)+'–'+pitchName(sorted.at(-1).pitch);}
function start(pool=null){clearTimeout(timer);clearInterval(clockTick);pool=pool||activePool();if(!pool.length||!canStart())return;advanceRemaining=null;advanceAt=null;practice=arguments.length>0;roundPool=practice?distinctMissed(pool):pool;round=newRound(practice?missedPracticeQueue(pool):makeQueue(pool,config.count));roundClock=newClock(performance.now(),!practice&&config.roundType==='timed'?config.duration:0);screen='play';updateNavigation();question(true);clockTick=setInterval(updateClock,200);}
function clockMarkup(){const elapsed=Math.min(elapsedMs(roundClock,performance.now()),roundClock.duration||Infinity);return `<div class="round-clock" aria-label="Elapsed time"><span aria-hidden="true">◷</span> <span id="elapsed-time">${formatTime(elapsed)}</span>${roundClock.duration?` <span class="time-limit">/ ${formatTime(roundClock.duration)}</span>`:''}</div>`;}
function updateClock(){if(screen!=='play'||!roundClock)return;const elapsed=Math.min(elapsedMs(roundClock,performance.now()),roundClock.duration||Infinity);const el=app.querySelector('#elapsed-time');if(el)el.textContent=formatTime(elapsed);if(roundClock.duration){const track=app.querySelector('.progress-track');if(track){track.setAttribute('aria-valuenow',Math.floor(elapsed/1000));track.firstElementChild.style.width=100*elapsed/roundClock.duration+'%';}if(!settingsDraft&&!modalPause&&timeExpired(roundClock,performance.now()))results(false,true);}}
function deadlineReached(){if(settingsDraft||modalPause||screen!=='play')return true;if(timeExpired(roundClock,performance.now())){results(false,true);return true;}return false;}
function stats(){return `<div class="stats"><div class="stat"><strong>${accuracy(round)===null?'—':accuracy(round)+'%'}</strong><span>accuracy</span></div><div class="stat"><strong>${round.streak}</strong><span>streak</span></div><div class="stat"><strong>${round.best}</strong><span>best</span></div></div>`;}
function scheduleAdvance(delay){clearTimeout(timer);advanceRemaining=delay;advanceAt=performance.now()+delay;if(settingsDraft||modalPause){advanceAt=null;return;}timer=setTimeout(()=>{advanceRemaining=null;advanceAt=null;if(deadlineReached())return;advance(round);question();},delay);}
function question(first=false){if(deadlineReached())return;const scrollY=window.scrollY,enlarged=first?preferences.chartSize==='large':!!app.querySelector('.woodwind-workbench.enlarged');advanceRemaining=null;advanceAt=null;if(round.index===round.queue.length){if(roundClock.duration){const batch=makeQueue(roundPool,config.count);if(batch.length>1&&batch[0].id===round.queue.at(-1).id)[batch[0],batch[1]]=[batch[1],batch[0]];round.queue.push(...batch);}else{results();return;}}answerView=null;selection={keys:[]};choices=choicesFor(round.queue[round.index],{...inst(),choicePool:activePool()},partials());const n=round.queue[round.index],i=inst();app.innerHTML=`<div class="exercise-top"><div><p class="eyebrow">${practice?'MISSED-NOTE PRACTICE':config.mode==='challenge'?'MULTIPLE CHOICE':'BUILD THE COMBINATION'}</p><h1>${i.name}</h1><p class="subtle">${levelName()} · ${practiceTitle()} · ${config.alternates?'alternates on':'primary fingerings'}</p></div><div class="play-tools">${clockMarkup()}<div id="stats">${stats()}</div><button id="play-gear" class="settings-gear" aria-label="Change settings" title="Change settings">${gearIcon()}</button></div></div><div class="progress-track" role="progressbar" aria-label="${roundClock.duration?'Time elapsed':'Round progress'}" aria-valuemin="0" aria-valuemax="${roundClock.duration?config.duration:round.queue.length}" aria-valuenow="${roundClock.duration?Math.floor(elapsedMs(roundClock,performance.now())/1000):round.index}"><div style="width:${roundClock.duration?elapsedMs(roundClock,performance.now())/roundClock.duration*100:round.index/round.queue.length*100}%"></div></div><section class="panel play-panel"><div class="prompt-row"><span>Question ${round.index+1}${roundClock.duration?' · timed challenge':' of '+round.queue.length}</span><span class="tag">Written pitch · ${i.clef} clef</span></div><div class="exercise-content ${config.mode==='challenge'?'multiple-choice-layout':i.kind==='woodwind'?'woodwind-workbench':''}"><div class="note-prompt"><div class="notation">${staff(n.pitch,i.clef)}</div><p class="instruction">${config.mode==='challenge'?'Which fingering plays this note?':(i.kind==='slide'?'Select the slide position for this note.':i.kind==='valves'?'Select the valves for this note.':'Select the keys for this note.')}</p>${i.kind==='valves'&&config.mode==='interactive'?`<p class="valve-shortcut-intro">${valveHint(i)}<br>Press again to release · Enter to check</p>`:''}</div>${config.mode==='challenge'?`<div class="choices ${i.kind==='woodwind'?'woodwind-choices':''}">${choices.map((f,j)=>`<button class="choice" data-choice="${j}" aria-label="Option ${choiceLabel(i,j)}: ${esc(captions(f))}"><span class="choice-index">${choiceLabel(i,j)}</span>${diagram(f)}</button>`).join('')}</div>`:`<div class="combination-controls">${interactive()}</div>`}</div><p class="legend"><span class="legend-dot filled"></span>Pressed / covered <span class="legend-dot"></span>Released</p><div class="answer-dock"><div id="feedback" class="feedback" role="status">${config.mode==='challenge'?'Choose one of the four fingering diagrams.':i.kind==='woodwind'?'Choose the keys you would use on your instrument.':'Choose a fingering, then check your answer.'}</div><div id="reveal-box"></div><div class="bottom-actions"><div class="small-actions"><button id="end" class="text-button">End round</button><button id="show" class="text-button">Show answer</button><button id="play-tone" class="text-button">Hear Tone</button></div>${config.mode==='interactive'?'<div class="small-actions"><button id="clear">Clear</button><button id="check" class="primary">Check answer</button></div>':`<span class="keyboard-help">Keyboard: ${i.kind==='valves'?'A–D':'1–4'} to choose</span>`}</div></div></section>`;
 app.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>check(choices[+b.dataset.choice],b));
 bindKeys();bindWoodwindDrag();app.querySelector('#play-gear')?.addEventListener('click',openPracticeSettings);app.querySelector('#end').onclick=()=>{clearTimeout(timer);results(true);};app.querySelector('#show').onclick=showAnswer;app.querySelector('#play-tone').onclick=()=>{if(!deadlineReached()){const note=round.queue[round.index];playNoteTone(note.midi,inst().transpose,inst().id,undefined,preferences.noteVolume);}};
 app.querySelector('#clear')?.addEventListener('click',()=>{selection={keys:[]};updateKeys();const s=app.querySelector('#partial');if(s)s.value='';});app.querySelector('#check')?.addEventListener('click',()=>check(selection));
 if(enlarged){app.querySelector('.woodwind-workbench')?.classList.add('enlarged');const size=app.querySelector('#chart-size');if(size){size.textContent='Compact chart';size.setAttribute('aria-expanded','true');}}
 window.scrollTo({top:first?0:scrollY,behavior:'instant'});updateNavigation();
 announce(`Question ${round.index+1}${roundClock.duration?' · timed challenge':' of '+round.queue.length}. ${config.mode==='interactive'?'Select keys, then check your answer.':'Choose a fingering.'}`);
}
function interactive(){
 const i=inst();if(i.kind==='woodwind')return woodwindChart(i,selection,true);
 const ordered=brassDisplayKeys(i);
 const groups=[...new Set(ordered.map(k=>k.group))];
 return `<div class="key-diagram ${i.kind}">${groups.map(g=>`<section class="key-group"><h3>${g}</h3><div class="key-list">${ordered.filter(k=>k.group===g).map(k=>`<button class="key ${isTriggerKey(k.id)?'trigger-key':''}" data-key="${k.id}" aria-pressed="false" aria-label="${esc(g+' '+k.label)}" ${i.kind==='valves'&&config.keyboard?`aria-keyshortcuts="${shortcutForValve(i,k.id,mapping())}"`:''}><span>${(k.id==='Bb'&&i.id==='horn')||k.id==='Trigger'?'T':k.label}</span>${i.kind==='valves'?`<kbd>${shortcutForValve(i,k.id,mapping())}</kbd>`:''}</button>`).join('')}</div></section>`).join('')}</div>${i.kind==='valves'?`<label class="keyboard-toggle"><input type="checkbox" id="keyboard-enabled" ${config.keyboard?'checked':''}> Enable valve keyboard shortcuts</label><p id="valve-selection" class="valve-selection" aria-live="polite">Open — no valves pressed</p>`:''}`;
}
function bindKeys(){app.querySelector('#chart-size')?.addEventListener('click',e=>{const big=app.querySelector('.woodwind-workbench').classList.toggle('enlarged');e.currentTarget.textContent=big?'Compact chart':'Enlarge chart';e.currentTarget.setAttribute('aria-expanded',String(big));});app.querySelector('#keyboard-enabled')?.addEventListener('change',e=>{config.keyboard=e.target.checked;app.querySelectorAll('[data-key]').forEach(b=>{if(config.keyboard)b.setAttribute('aria-keyshortcuts',shortcutForValve(inst(),b.dataset.key,mapping()));else b.removeAttribute('aria-keyshortcuts');});});app.querySelector('#hole-coverage')?.addEventListener('change',e=>{if(round.solved)return;selection.keys=selection.keys.filter(k=>k!=='L1'&&!k.startsWith('L1:'));if(e.target.value)selection.keys.push(e.target.value);updateKeys();});app.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{if(round.solved)return;const k=b.dataset.key;if(k==='L1'&&inst().kind==='woodwind'&&holeStates(inst()).length>1){selection.keys=cycleHole(inst(),selection.keys);}else if(inst().kind==='slide'&&k.startsWith('P')){selection.keys=[...selection.keys.filter(x=>!x.startsWith('P')),k];}else if(inst().kind==='slide'&&['Flat','Sharp'].includes(k)){const was=selection.keys.includes(k);selection.keys=selection.keys.filter(x=>!['Flat','Sharp'].includes(x));if(!was)selection.keys.push(k);}else if(selection.keys.includes(k)){selection.keys=selection.keys.filter(x=>x!==k);}else{if(k.startsWith('L1'))selection.keys=selection.keys.filter(x=>!x.startsWith('L1'));if(inst().id==='flute'&&['T','BbT'].includes(k))selection.keys=selection.keys.filter(x=>!['T','BbT'].includes(x));selection.keys.push(k);}updateKeys();});}
function bindWoodwindDrag(){if(inst().kind==='woodwind')bindChartDrag(app.querySelector('.chart-interactive'),{instrument:inst(),getKeys:()=>selection.keys,setKeys:keys=>{selection.keys=keys;updateKeys();},locked:()=>round.solved||settingsDraft});}
function updateKeys(){app.querySelector('.play-panel')?.classList.remove('answer-incorrect');if(inst().kind==='woodwind'){updateWoodwindChart(app,inst(),selection.keys);return;}app.querySelectorAll('[data-key]').forEach(b=>b.setAttribute('aria-pressed',String(selection.keys.includes(b.dataset.key))));const summary=app.querySelector('#valve-selection');if(summary)summary.textContent=selection.keys.length?captions(selection):'Open — no valves pressed';}
function answerTone(){const current=round,index=round.index,n=round.queue[index];playAnswerTone(n.midi,inst().transpose,inst().id,()=>{if(screen==='play'&&round===current&&round.index===index&&round.solved&&!answerView?.manualNext)scheduleAdvance(NOTE_TONE_MS);},preferences.correctSound,preferences.noteVolume);}
function check(f,button){if(deadlineReached()||round.solved)return;if(partials()&&!f.partial){feedback('Choose a harmonic partial before checking.','bad');return;}if(inst().kind==='slide'&&!f.keys.some(k=>k.startsWith('P'))){feedback('Choose a slide position before checking.','bad');return;}const ok=submit(round,f,partials());document.querySelector('#stats').innerHTML=stats();if(ok){app.querySelector('.play-panel').classList.remove('answer-incorrect');button?.classList.add('good');feedback(`Correct · ${pitchName(round.queue[round.index].pitch)}${round.attempted&&round.missed.some(n=>n.id===round.queue[round.index].id)?' — keep practicing this one.':''}`,'good');lock();if(config.alternates&&answerFingerings(round.queue[round.index],true).length>1)displayAcceptedAnswer();answerTone();}else{if(preferences.wrongSound)playIncorrectTone(preferences.wrongVolume);app.querySelector('.play-panel').classList.add('answer-incorrect');button?.classList.add('bad');feedback('Not quite. Adjust your answer and try again, or show the fingering.','bad');}}
function feedback(text,type){const el=app.querySelector('#feedback');el.className='feedback '+type;el.textContent=text;}
function lock(){app.querySelectorAll('[data-choice],[data-key],#check,#clear,#show,#partial,#hole-coverage').forEach(b=>b.disabled=true);}
function answerNavigation(){return `<div class="answer-navigation"><button type="button" class="answer-arrow" data-answer-step="-1" aria-label="Previous accepted fingering" title="Previous accepted fingering">‹</button><button type="button" class="answer-arrow" data-answer-step="1" aria-label="Next accepted fingering" title="Next accepted fingering">›</button></div>`;}
function updateAcceptedAnswer(){
 if(screen!=='play'||!round.solved||!answerView)return;
 const n=round.queue[round.index],f=answerView.fingerings[answerView.index];
 if(config.mode==='interactive'){selection={keys:[...f.keys]};updateKeys();}
 else app.querySelector('.answer-preview').innerHTML=diagram(f);
 const label=answerView.index===0?'Main fingering':'Alternate '+answerView.index;
 app.querySelector('#answer-variant-label').textContent=label+(answerView.fingerings.length>1?' · '+(answerView.index+1)+' of '+answerView.fingerings.length:'');
 app.querySelector('#answer-fingering-caption').textContent=inst().kind==='woodwind'?'Green keys show this accepted fingering.':captions(f);
 announce(pitchName(n.pitch)+'. '+label+'. '+captions(f));
}
function displayAcceptedAnswer(){
 const n=round.queue[round.index],fingerings=answerFingerings(n,config.alternates);
 answerView={fingerings,index:0,manualNext:!roundClock.duration};
 app.querySelector('.play-panel').classList.add('answer-revealed');
 if(config.mode==='challenge'){
  const primary=choices.findIndex(f=>[...f.keys].sort().join()===[...n.fingerings[0].keys].sort().join());
  const card=app.querySelector(`[data-choice="${primary}"]`);
  const replacement=document.createElement('div');replacement.className='choice revealed-correct answer-choice';
  replacement.innerHTML=`<span class="choice-index">${choiceLabel(inst(),primary)}</span><div class="answer-preview"></div>${fingerings.length>1?answerNavigation():''}`;card.replaceWith(replacement);
 }else if(fingerings.length>1){(app.querySelector('.woodwind-interactive')||app.querySelector('.key-diagram')).insertAdjacentHTML('beforeend',answerNavigation());}
 app.querySelector('#reveal-box').innerHTML=`<div class="reveal-summary"><div><strong id="answer-variant-label" class="answer-variant-label" aria-live="polite"></strong><span id="answer-fingering-caption"></span></div><details><summary>Fingering details${fingerings.length>1?' & alternatives':''}</summary>${fingerings.map((f,j)=>`<p>${j===0?'Main':'Alternate '+j}: ${esc(captions(f))}</p>`).join('')}${n.tip?`<p>${esc(n.tip)}</p>`:''}</details></div>`;
 app.querySelectorAll('[data-answer-step]').forEach(b=>b.onclick=()=>{
  if(deadlineReached()||!round.solved||!answerView)return;
  answerView.index=nextAnswerIndex(answerView.index,+b.dataset.answerStep,answerView.fingerings.length);updateAcceptedAnswer();
 });
 const hint=app.querySelector('.woodwind-interactive .chart-help');if(hint)hint.textContent=fingerings.length>1?'Use the arrows to compare accepted fingerings.':'Correct fingering shown.';
 updateAcceptedAnswer();app.querySelector('.keyboard-help')?.remove();app.querySelector('#check')?.remove();app.querySelector('#clear')?.remove();
 const next=document.createElement('button');next.id='next';next.className='primary';next.textContent=roundClock.duration?'Next note after tone…':'Next note →';app.querySelector('.bottom-actions').append(next);
 next.onclick=()=>{if(deadlineReached())return;clearTimeout(timer);advanceRemaining=null;advanceAt=null;advance(round);question();};next.focus({preventScroll:true});
}
function showAnswer(){
 if(deadlineReached()||round.solved)return;reveal(round);document.querySelector('#stats').innerHTML=stats();lock();const n=round.queue[round.index];
 feedback(pitchName(n.pitch)+' — correct fingering shown.','good');displayAcceptedAnswer();
 if(roundClock.duration)answerTone();else playAnswerTone(n.midi,inst().transpose,inst().id,undefined,preferences.correctSound,preferences.noteVolume);
}
function results(early=false,expired=false){screen='results';updateNavigation();clearTimeout(timer);clearInterval(clockTick);pauseClock(roundClock,performance.now());const completed=round.index+(round.solved?1:0);const missed=distinctMissed(round.missed);const a=accuracy(round);app.innerHTML=`<section class="panel result"><div class="result-hero"><p class="eyebrow">${expired?'TIME’S UP':early?'ROUND ENDED':'ROUND COMPLETE'}</p><h1>${a===100?'Every note connected.':a!==null&&a>=80?'You’re finding your flow.':'One note at a time.'}</h1><div class="score">${roundClock.duration?round.correct:a===null?'—':a+'%'}</div>${roundClock.duration?'<p>notes answered correctly</p>':''}<p class="subtle">Time: ${formatTime(Math.min(elapsedMs(roundClock,performance.now()),roundClock.duration||Infinity))}${roundClock.duration?' · '+(a===null?'—':a+'%')+' first-attempt accuracy':''}</p><p class="subtle">First-attempt accuracy · ${inst().name}</p><div class="result-stats"><div class="stat"><strong>${completed}${roundClock.duration?'':'/'+round.queue.length}</strong><span>completed</span></div><div class="stat"><strong>${round.best}</strong><span>best streak</span></div><div class="stat"><strong>${missed.length}</strong><span>notes to revisit</span></div></div></div><div class="result-actions">${missed.length?'<button id="practice" class="primary">Practice missed notes</button>':''}<button id="again" ${missed.length?'':'class="primary"'}>Play another round</button><button id="settings">Change settings</button></div>${missed.length?`<h2>Notes to revisit</h2><p class="subtle">Accepted fingerings are listed below. Practice uses only these pitches in a new ${Math.min(10,missed.length*3)}-question round.</p><div class="answer-list">${missed.map(n=>`<div class="answer-row">${staff(n.pitch,inst().clef)}<div><strong>${pitchName(n.pitch)}</strong>${n.fingerings.map(f=>`<p>${esc(captions(f,inst(),false))}</p>`).join('')}${n.tip?`<p>${esc(n.tip)}</p>`:''}</div></div>`).join('')}</div>`:'<p class="subtle" style="text-align:center">'+(completed?'No missed notes in this round.':'No notes answered yet.')+'</p>'}</section>`;app.querySelector('#practice')?.addEventListener('click',()=>start(missed));app.querySelector('#again').onclick=()=>start();app.querySelector('#settings').onclick=setup;announce('Round complete. '+(a===null?'No answers yet.':a+' percent first-attempt accuracy.'));app.querySelector('#practice,#again').focus();}
function guide(i=inst()){document.querySelector('#guide-content').innerHTML=`<h3>How to play</h3><p>Read the written note. In Multiple Choice, click a diagram or use its displayed shortcut: A–D for valved brass, 1–4 for the other instruments. In Build the Combination, toggle each key, hole, valve, or position and select <strong>Check answer</strong>. Use Tab to move between controls and Space to select them. On woodwinds, drag over a released key to press it, or a pressed key to release it. Leave a key and pass over it again to toggle it again. Tab to Check answer and press Enter to submit.</p>${i.kind==='valves'?`<h3>Valve keyboard shortcuts</h3><p>${valveHint(i)}. These work in Build the Combination only. Multiple Choice uses diagram choices only. Each press toggles a valve; Enter checks your built fingering, including open notes with no valves selected. Clicking a valve uses the same selection. Repeated key presses while holding a key are ignored. Disable these shortcuts with the checkbox below the valves.</p>`:''}<p>Correct answers play an instrument-style tone at sounding pitch, fading during the final half-second. Hear Tone replays the note at any point. Timed rounds advance when the one-second answer tone finishes, including Show answer. A wrong attempt stays on the note and counts as a miss. Appearance & Sound has separate Appearance and Sound sections. Change colors, dark mode, and chart size under Appearance. Under Sound, set the note and incorrect-answer volumes, toggle automatic correct/incorrect sounds, or restore sound defaults. Hear Tone remains available when automatic answer tones are disabled. Accuracy counts notes answered correctly on the first attempt. Showing an answer counts as a miss. Alternate fingerings start disabled. When enabled, revealed charts start with the main fingering and side arrows browse the accepted alternatives. In question rounds, a correct answer with alternatives stays visible until Next note is pressed; timed rounds keep automatic advancement. End the round at any time to review and practice missed notes. Missed-note practice uses three questions per distinct pitch, capped at ten questions, even after a timed round.</p><h3>${i.name}: ${i.system}</h3><p>${i.description}</p><p>The flute chart follows the horizontal instrument; the other woodwinds use vertical body layouts. Main holes, side keys, thumb controls, and pinkie clusters follow their positions on an instrument fingering chart. Key faces are unlabeled; accessible names remain available to screen readers. Compact spacing follows the supplied school-band chart; exact hardware varies by instrument model. L1/L2/L3 and R1/R2/R3 mean index/middle/ring fingers. Key names are available below for reference and to screen readers; they are not printed on the chart. The same key may have two note names in different registers.</p>${i.kind!=='woodwind'?'<p>Valves and slide positions alone do not determine a note. Air and embouchure select the register. The game checks only valves or slide positions, at every tier. Pitch still needs adjustment by ear; trombone alternatives marked ♯ or ♭ require the corresponding slide-adjustment button. T means trigger. These symbols modify the slide position, not the written pitch.</p>':''}${i.id==='bassoon'?'<p>L1 fraction controls specify the proportion of the first hole covered. Flick keys are momentary at the attack, not held throughout a note; this trainer checks sustained basic fingerings.</p>':''}${i.kind==='woodwind'?`<details class="key-legend"><summary>Key legend · ${i.name}</summary><table class="guide-table"><tr><th>Code</th><th>Key / hole</th><th>Hand / group</th></tr>${i.keys.map(k=>`<tr><td>${esc(k.id)}</td><td>${esc(k.label)}</td><td>${esc(k.group)}</td></tr>`).join('')}</table></details>`:''}<h3>Levels and custom ranges</h3><p>On Practice, Beginner uses five concert-scale notes, Intermediate adds a larger chromatic range, and Advanced uses the full verified range. Choose Custom to open Advanced Setup. There, First notes practices the first five notes of concert B♭ major. Build your range extends that scale to an octave. Horn also offers concert F. Chromatic notes adds notes outside that concert key; written key-signature accidentals remain available when it is off. Choose Customized to set the lowest and highest written notes with the arrows or sliders. Filter individual spellings and accidentals. Extended range selects only the outer registers and excludes the middle. On saxophones it emphasizes low C and below and high D and above. Only notes in the verified dataset are offered; double accidentals are not included.</p><h3>Timed practice</h3><p>The stopwatch measures elapsed play in both modes. Timed challenges stop at the chosen limit and count correct answers; revealed answers do not score. Opening Practice Settings pauses time. Cancel resumes; applying changed options starts a fresh round.</p><h3>Dataset reference ranges</h3><table class="guide-table"><tr><th>Tier</th><th>Focus</th><th>Written range</th></tr>${tiers.map((t,j)=>`<tr><td>${j+1}</td><td>${t.name}</td><td>${rangeText(poolFor(i,j+1))}</td></tr>`).join('')}</table><h3>Scope & references</h3><p>Ranges are selected school-band practice ranges, not the full possible compass of each instrument. Common sustained fingerings and selected alternatives are accepted; specialized trills, microtones, model-dependent altissimo, and every possible alternate are outside this set. Instrument configuration is stated on the start screen.</p><p>The fingering facts are encoded separately from the game. Chart artwork is not copied. The tier sequence is an instructional design choice, not a sequence prescribed by the sources.</p>${[...new Set(i.notes.flatMap(n=>n.sources))].map(s=>sources[s].url?`<a class="source-link" href="${sources[s].url}" target="_blank" rel="noopener">${sources[s].title} ↗</a>`:`<p class="source-link">${esc(sources[s].title)} · supplied PDF</p>`).join('')}<p class="subtle">Data edition: September 2026. See the project README for coverage, cross-checks, and extension instructions. Clefs and accidentals use Steinberg’s Bravura music font (SIL Open Font License).</p>`;pauseForModal(document.querySelector('#guide-dialog'));document.querySelector('#guide-dialog').showModal();}
document.querySelector('#silhouette-assets').innerHTML=silhouetteDefinitions();
document.querySelector('.brand-mark').innerHTML=questLogo();
document.querySelector('.quest-banner-art').innerHTML=questBannerArt();
document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home');};
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
document.querySelector('#close-guide').onclick=()=>document.querySelector('#guide-dialog').close();document.querySelector('#guide-dialog').onclick=e=>{if(e.target===e.currentTarget)e.currentTarget.close();};
document.addEventListener('keydown',e=>{
 const editingText=['SELECT','TEXTAREA'].includes(e.target.tagName)||(e.target.tagName==='INPUT'&&!['checkbox','radio'].includes(e.target.type))||e.target.isContentEditable;
 const state={instrument:inst(),mode:config.mode,enabled:config.keyboard,screen,solved:round?.solved,dialogOpen:!!document.querySelector('dialog[open]'),editingText,mapping:mapping()};
 const action=keyboardAction(e,state);
 if(action){e.preventDefault();if(action.type==='choice'){app.querySelector(`[data-choice="${action.index}"]`)?.click();}else{const button=app.querySelector(`[data-key="${action.id}"]`);button?.click();button?.focus({preventScroll:true});}return;}
 if(screen!=='play'||round.solved||state.dialogOpen||editingText||e.repeat||e.altKey||e.ctrlKey||e.metaKey)return;
 // Enter submits from a valve key or the page. Other focused buttons retain
 // normal activation, so End round, Show answer, and answer choices stay usable.
 if(e.key==='Enter'&&e.target.tagName!=='INPUT'&&(config.mode==='interactive')&&(!['BUTTON','A','SUMMARY'].includes(e.target.tagName)||e.target.hasAttribute('data-key'))){e.preventDefault();app.querySelector('#check')?.click();}
});
function loadSharedSettings(){
 settingsDraft=false;savedConfig=null;
 const sharedToken=new URLSearchParams(location.hash.slice(1)).get('settings');
 const shared=sharedToken?decodeSettings(sharedToken):null;
 if(shared)config={...config,...shared,maps:{...config.maps,...shared.maps}};
 instrumentChosen=!!shared;config.custom=config.custom||defaultPractice(inst());navigate(shared?'practice':'home');
 if(sharedToken){const status=app.querySelector('#shared-status')||document.querySelector('#announcement');status.textContent=shared?'Shared practice settings loaded.':'This settings link could not be read. Choose your instrument to begin.';}
}
window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());loadSharedSettings();});
loadSharedSettings();
